// AST for the nsh shell language.

#[derive(Debug, Clone, PartialEq)]
pub enum ParamOp {
    Default,      // :-
    Assign,       // :=
}

#[derive(Debug, Clone)]
pub enum Part {
    /// unquoted literal characters (escapes already resolved)
    Literal(String),
    /// `~...` tilde prefix
    Tilde(String),
    /// `'...'`
    SingleQuoted(String),
    /// `"..."` (inner parts may expand)
    DoubleQuoted(Vec<Part>),
    /// `$name` / `${name}`
    Param(String),
    /// `${name:-word}` / `${name:=word}`
    ParamEx { name: String, op: ParamOp, word: Vec<Part> },
    /// `$((expr))`
    Expr(String),
    /// `$(...)`
    CommandSub(Box<CompoundList>),
    /// `` `...` ``
    Backtick(Box<CompoundList>),
    /// `<(cmd)` / `>(cmd)`
    ProcSubst { input: bool, list: Box<CompoundList> },
}

#[derive(Debug, Clone)]
pub struct Word {
    pub parts: Vec<Part>,
    /// byte offsets in the original source
    pub start: usize,
    pub end: usize,
}

#[derive(Debug, Clone)]
pub enum RedirectOp {
    In,        // <
    Out,       // >
    Append,    // >>
    DupOut,    // >&N / &>file
    DupIn,     // <&N
}

#[derive(Debug, Clone)]
pub struct Redirect {
    pub fd: Option<usize>,
    pub op: RedirectOp,
    pub target: Word,
    pub dup: bool,
}

#[derive(Debug, Clone)]
pub struct Assign {
    pub name: String,
    pub value: Vec<Part>,
}

#[derive(Debug, Clone)]
pub struct CaseArm {
    pub patterns: Vec<Word>,
    pub body: CompoundList,
}

#[derive(Debug, Clone)]
pub enum Command {
    Simple {
        assigns: Vec<Assign>,
        words: Vec<Word>,
        redirects: Vec<Redirect>,
    },
    If {
        cond: CompoundList,
        then: CompoundList,
        elifs: Vec<(CompoundList, CompoundList)>,
        els: Option<CompoundList>,
    },
    While {
        until: bool,
        cond: CompoundList,
        body: CompoundList,
    },
    For {
        var: String,
        words: Vec<Word>,
        body: CompoundList,
    },
    ForArith {
        init: Option<String>,
        cond: Option<String>,
        incr: Option<String>,
        body: CompoundList,
    },
    Case {
        word: Word,
        arms: Vec<CaseArm>,
    },
    Func {
        name: String,
        body: CompoundList,
    },
    Subshell(CompoundList),
    Group(CompoundList),
}

#[derive(Debug, Clone)]
pub struct Pipeline {
    pub commands: Vec<Command>,
    /// negated (`!`) pipelines are not supported by nsh
    pub async_: bool,
}

#[derive(Debug, Clone)]
pub struct AndOr {
    pub ops: Vec<bool>,  // true == `&&`
    pub pipelines: Vec<Pipeline>,
}

pub type CompoundList = Vec<AndOr>;
