// Hand written recursive-descent parser that mirrors the pest grammar used by nsh,
// including pest-style error reporting (`expected ...` / `unexpected ...`).

use crate::ast::*;
use crate::rule::Rule;

pub struct ParseError {
    pub pos: usize,
    pub positives: Vec<Rule>,
    pub negatives: Vec<Rule>,
}

impl ParseError {
    pub fn format(&self, input: &str) -> String {
        let (line, col, line_text) = locate(input, self.pos);
        let width = line.to_string().len();
        let sp = " ".repeat(width + 1);
        let mut out = String::new();
        out.push_str(&format!("{}--> {}:{}\n", " ".repeat(width + 2), line, col));
        out.push_str(&format!("{}|\n", sp));
        out.push_str(&format!("{} | {}\n", line, line_text));
        // underline: reproduce tabs of the original line
        let mut under = String::new();
        for c in line_text.chars().take(col - 1) {
            if c == '\t' {
                under.push('\t');
            } else {
                under.push(' ');
            }
        }
        out.push_str(&format!("{}| {}^---\n", sp, under));
        out.push_str(&format!("{}|\n", sp));
        out.push_str(&format!("{}= {}\n", sp, self.expected_str()));
        out
    }

    fn join(&self, v: &[Rule]) -> String {
        let mut s = String::new();
        for (i, r) in v.iter().enumerate() {
            if i > 0 {
                if i + 1 == v.len() {
                    s.push_str(", or ");
                } else {
                    s.push_str(", ");
                }
            }
            s.push_str(&format!("{:?}", r));
        }
        s
    }

    fn expected_str(&self) -> String {
        let mut exp: Vec<Rule> = self.positives.clone();
        exp.sort();
        exp.dedup();
        let mut neg: Vec<Rule> = self.negatives.clone();
        neg.sort();
