    }
    /// skip whitespace and comments (comment only valid at the beginning of a word)
    fn skip_trivia(&mut self) {
        self.skip_space_all();
        if self.cur() == b'#' {
            while !self.eof() && self.b[self.pos] != b'\n' {
                self.pos += 1;
            }
            self.skip_space_all();
        }
    }

    fn newline(&mut self) -> bool {
        if self.at("\n") {
            self.pos += 1;
            true
        } else if self.at("\r\n") {
            self.pos += 2;
            true
        } else {
            false
        }
    }

    /// `compound_list_sep`
    fn compound_list_sep(&mut self) -> PResult<()> {
        self.rule(Rule::compound_list_sep, |p| {
            p.skip_trivia();
            if p.pos >= p.b.len() {
                return None;
            }
            // `;;` is the case terminator and is not a list separator
            if p.at(";;") {
                return None;
            }
            if p.at(";") {
                p.pos += 1;
                return Some(());
            }
            if p.at("&") && !p.at("&&") {
                p.pos += 1;
                return Some(());
            }
            None
        })
    }

    fn normal_newline(&mut self) -> PResult<()> {
        self.rule(Rule::normal_newline, |p| {
            p.skip_trivia();
            if p.newline() {
                Some(())
            } else {
                None
            }
        })
    }

    fn and_or_list_sep(&mut self) -> PResult<bool> {
        self.rule(Rule::and_or_list_sep, |p| {
            p.skip_trivia();
            if p.at("&&") {
                p.pos += 2;
                Some(true)
            } else if p.at("||") {
                p.pos += 2;
                Some(false)
            } else {
                None
            }
        })
    }

    fn eoi(&mut self) -> PResult<()> {
        self.rule(Rule::EOI, |p| {
            p.skip_trivia();
            if p.eof() {
                Some(())
            } else {
                None
            }
        })
    }

    // ---------------------------------------------------------------- program
    pub fn program(&mut self) -> PResult<CompoundList> {
        let mut list: CompoundList = Vec::new();
        loop {
            while self.compound_list_sep().is_some() {
                // skip
            }
            if let Some(ao) = self.and_or() {
                list.push(ao);
            } else {
                break;
            }
        }
        self.trailing_seps();
        if self.eoi().is_none() {
            return None;
        }
        Some(list)
    }

    fn trailing_seps(&mut self) {
        loop {
            if self.compound_list_sep().is_some() {
                continue;
            }
            if self.normal_newline().is_some() {
                continue;
            }
            break;
        }
    }

    fn and_or(&mut self) -> PResult<AndOr> {
        let mut ops: Vec<bool> = Vec::new();
        let mut pipelines: Vec<Pipeline> = Vec::new();
        let first = self.pipeline()?;
        pipelines.push(first);
        loop {
            if let Some(and) = self.and_or_list_sep() {
                self.normal_newline();
                if let Some(pl) = self.pipeline() {
                    ops.push(and);
                    pipelines.push(pl);
                } else {
                    return None;
                }
            } else {
                break;
            }
        }
        Some(AndOr { ops, pipelines })
    }

    fn pipeline(&mut self) -> PResult<Pipeline> {
        let mut commands: Vec<Command> = Vec::new();
        let mut async_ = false;
        let first = self.command()?;
        commands.push(first);
        loop {
            self.normal_newline();
            if self.at("|") && !self.at("||") {
                self.pos += 1;
                self.normal_newline();
                if let Some(c) = self.command() {
                    commands.push(c);
                } else {
                    return None;
                }
            } else {
                break;
            }
        }
        self.skip_trivia();
        if self.at("&") && !self.at("&&") {
            self.pos += 1;
            async_ = true;
        }
        Some(Pipeline {
            commands,
            async_,
        })
    }

    // ---------------------------------------------------------------- command
    fn command(&mut self) -> PResult<Command> {
        self.rule(Rule::command, |p| {
            p.subshell()
                .or_else(|_| p.brace_group())
                .or_else(|_| p.if_rule())
                .or_else(|_| p.while_rule(true))
                .or_else(|_| p.while_rule(false))
                .or_else(|_| p.for_rule())
                .or_else(|_| p.case_rule())
                .or_else(|_| p.func_def())
                .or_else(|_| p.simple_command())
        })
    }
}
